 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append(cells)
    cells = max(comps, key=lambda comp: len({grid[r][c] for r,c in comp}))
    r0 = min(r for r,c in cells); r1 = max(r for r,c in cells)
    c0 = min(c for r,c in cells); c1 = max(c for r,c in cells)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]
